const update = $input.first().json;
const sd = $getWorkflowStaticData('global');

function home() {
  sd.mode = '';
  sd.review = null;
  return { route: 'menu_home', chat_id: arguments[0] };
}

if (update.callback_query) {
  const cb = update.callback_query;
  const data = String(cb.data || '');
  const chatId = cb.message?.chat?.id;
  const base = {
    callback_id: cb.id,
    callback_data: data,
    chat_id: chatId,
    user_id: String(cb.from?.id || ''),
    ack: 'OK'
  };

  // Survey votes (from V2)
  if (data.startsWith('v|')) {
    const parts = data.split('|');
    const account = parts[1] || '';
    const code = parts[2] || '';
    const STATUS = { ca:'Call Again', na:'No Answer 1-5', n5:'No Answer 5 UP', rc:'Recall', ni:'No Interest', np:'No Potential', wn:'Wrong Number or Email', dr:'Denied Registration', keep:'Keep CRM' };
    return [{ json: { ...base, route: 'vote', account, status: STATUS[code]||code, code, vote_ack: (code==='ok'||code==='ai') ? `Accept AI saved for ${account} (V2 will resolve AI status)` : `Saved: ${account} -> ${STATUS[code]||code}`, ack: (code==='ok'||code==='ai') ? 'Accept AI' : 'Saved' } }];
  }

  if (data === 'm:home' || data === 'm:start') {
    sd.mode = ''; sd.review = null;
    return [{ json: { ...base, route: 'menu_home', ack: 'Menu' } }];
  }
  if (data === 'm:db') {
    sd.mode = ''; sd.review = null;
    return [{ json: { ...base, route: 'menu_db', ack: 'Database check' } }];
  }
  if (data === 'm:rules') {
    sd.mode = ''; sd.review = null;
    return [{ json: { ...base, route: 'menu_rules', ack: 'Rules' } }];
  }
  if (data === 'm:review') {
    sd.mode = 'review';
    return [{ json: { ...base, route: 'menu_review_start', ack: 'Review' } }];
  }
  if (data === 'm:ask') {
    sd.mode = 'ask';
    return [{ json: { ...base, route: 'menu_ask', ack: 'Ask mode' } }];
  }

  // Review actions
  if (data === 'rev:ok' || data === 'rev:skip' || data === 'rev:next') {
    return [{ json: { ...base, route: 'review_next', action: data.slice(4), ack: data === 'rev:ok' ? 'Correct' : 'Next' } }];
  }
  if (data === 'rev:bad') {
    return [{ json: { ...base, route: 'review_wrong', ack: 'Wrong' } }];
  }
  if (data === 'rev:exit') {
    sd.mode = ''; sd.review = null;
    return [{ json: { ...base, route: 'menu_home', ack: 'Exit review' } }];
  }
  if (data.startsWith('fix:')) {
    const code = data.slice(4);
    const STATUS = { ca:'Call Again', na:'No Answer 1-5', n5:'No Answer 5 UP', rc:'Recall', ni:'No Interest', np:'No Potential', wn:'Wrong Number or Email', dr:'Denied Registration', mc:'Manual Check', keep:'Keep as-is' };
    return [{ json: { ...base, route: 'review_fix', fix_code: code, fix_status: STATUS[code]||code, ack: STATUS[code]||code } }];
  }

  // unknown callback -> home
  return [{ json: { ...base, route: 'menu_home', ack: 'OK' } }];
}

const message = update.message || {};
const chatId = message.chat?.id;
const text = String(message.text || '').trim();
const low = text.toLowerCase();

if (text.startsWith('/start') || low === 'menu') {
  sd.mode = ''; sd.review = null;
  return [{ json: { route: 'menu_home', chat_id: chatId } }];
}

if (message.document) {
  return [{ json: {
    route: 'document', chat_id: chatId,
    file_id: message.document.file_id,
    file_name: message.document.file_name || 'upload.xlsx',
    mime_type: message.document.mime_type || ''
  }}];
}

// Ask mode: free text comment to match against sheet
if (sd.mode === 'ask' && text) {
  if (low === 'exit' || low === '/exit') {
    sd.mode = '';
    return [{ json: { route: 'menu_home', chat_id: chatId } }];
  }
  return [{ json: { route: 'ask_text', chat_id: chatId, text } }];
}

// Fallbacks if buttons fail
if (low === '1' || low === 'database' || low === 'database check') {
  return [{ json: { route: 'menu_db', chat_id: chatId, callback_id: '' } }];
}
if (low === '2' || low === 'rules') {
  return [{ json: { route: 'menu_rules', chat_id: chatId, callback_id: '' } }];
}

return [{ json: { route: 'menu_home', chat_id: chatId } }];

const chatId = $json.chat_id;
const hasCb = !!$json.callback_id;
return [{ json: {
  chat_id: chatId,
  callback_id: $json.callback_id || '',
  ack: $json.ack || 'Menu',
  has_cb: hasCb,
  text: "Choose an option (tap a button):",
  reply_markup: {
    inline_keyboard: [
      [{ text: "Database check", callback_data: "m:db" }],
      [{ text: "Rules (Google Sheet)", callback_data: "m:rules" }]
    ]
  }
}}];

return [{ json: {
  chat_id: $json.chat_id,
  callback_id: $json.callback_id || '',
  ack: 'Send your file',
  text: "Database check selected.\nPlease send your Excel/CSV file now.",
  reply_markup: {
    inline_keyboard: [[{ text: "Back to menu", callback_data: "m:home" }]]
  }
}}];

return [{ json: {
  chat_id: $json.chat_id,
  callback_id: $json.callback_id || '',
  ack: 'Rules',
  text: "Rules - what do you want to do?",
  reply_markup: {
    inline_keyboard: [
      [{ text: "Review sheet rules", callback_data: "m:review" }],
      [{ text: "Ask about a comment", callback_data: "m:ask" }],
      [{ text: "Back", callback_data: "m:home" }]
    ]
  }
}}];

const sd = $getWorkflowStaticData('global');
sd.mode = 'ask';
return [{ json: {
  chat_id: $json.chat_id,
  callback_id: $json.callback_id || '',
  ack: 'Ask mode',
  text: "Ask mode ON.\nPaste one CRM comment/phrase and I will show matching Google Sheet rows.\n\nOr tap Back.",
  reply_markup: {
    inline_keyboard: [[{ text: "Back to Rules", callback_data: "m:rules" }]]
  }
}}];

return [{ json: {
  chat_id: $json.chat_id,
  callback_id: $json.callback_id || '',
  ack: 'Loading sheet',
  _go_sheet: true
}}];

const sd = $getWorkflowStaticData('global');
function safe(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]()~>#+\-=|{}.!\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const chatId = $('Prep Review Start').item.json.chat_id || $('Route Update').item.json.chat_id;
const rows = $input.all().map(i => i.json).filter(j => j && (j.trigger_phrase || j.Trigger));
const active = rows.filter(j => String(j.active ?? 'true').toLowerCase() !== 'false');
const queue = active.map((j, idx) => ({
  row: j.row_number ?? j.rowNumber ?? j.row ?? (idx + 2),
  trigger: String(j.trigger_phrase || j.Trigger || '').trim(),
  status: String(j.suggested_status || j.first_status || '').trim(),
  group: String(j.keyword_group || 'other').trim() || 'other',
  repeat: String(j.repeat_logic || '').trim(),
  first: String(j.first_status || '').trim(),
  again: String(j.repeat_status || '').trim(),
  source: String(j.source || '').trim(),
}));
sd.review = { i: 0, chat_id: chatId, total: queue.length };
sd.reviewQueue = queue;
if (!queue.length) {
  return [{ json: {
    chat_id: chatId,
    text: 'No active sheet rules found.',
  }}];
}
const r = queue[0];
const text =
`Sheet review 1/${queue.length}\n` +
`Row ${safe(r.row)} | group: ${safe(r.group)}\n` +
`Trigger: ${safe(r.trigger)}\n` +
`Suggested: ${safe(r.status) || '-'}\n` +
(r.repeat ? `Repeat: ${safe(r.repeat)}\n` : '') +
`\nIs this rule correct?`;
return [{ json: { chat_id: chatId, text } }];

const prep = $('Prep Review Start').item.json;
const sd = $getWorkflowStaticData('global');
sd._rulesMsg = { chat_id: prep.chat_id };
return [{ json: { chat_id: prep.chat_id, callback_id: prep.callback_id || '', ack: prep.ack || '' } }];

const sd = $getWorkflowStaticData('global');
function safe(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]()~>#+\-=|{}.!\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const chatId = $json.chat_id;
const queue = Array.isArray(sd.reviewQueue) ? sd.reviewQueue : [];
if (!sd.review) sd.review = { i: 0, chat_id: chatId, total: queue.length };
sd.review.i = Math.min((sd.review.i || 0) + 1, queue.length);
const i = sd.review.i;
if (i >= queue.length) {
  sd.mode = '';
  sd.review = null;
  return [{ json: {
    chat_id: chatId,
    callback_id: $json.callback_id || '',
    ack: $json.ack || 'Done',
    text: `Review finished. Checked ${queue.length} sheet rules.`,
  }}];
}
const r = queue[i];
const text =
`Sheet review ${i+1}/${queue.length}\n` +
`Row ${safe(r.row)} | group: ${safe(r.group)}\n` +
`Trigger: ${safe(r.trigger)}\n` +
`Suggested: ${safe(r.status) || '-'}\n` +
(r.repeat ? `Repeat: ${safe(r.repeat)}\n` : '') +
`\nIs this rule correct?`;
return [{ json: {
  chat_id: chatId,
  callback_id: $json.callback_id || '',
  ack: $json.ack || 'Next',
  text,
}}];

const sd = $getWorkflowStaticData('global');
function safe(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]()~>#+\-=|{}.!\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const chatId = $json.chat_id;
const queue = sd.reviewQueue || [];
const i = (sd.review && sd.review.i) || 0;
const r = queue[i] || {};
return [{ json: {
  chat_id: chatId,
  callback_id: $json.callback_id || '',
  ack: 'Choose correct status',
  text: `Row ${safe(r.row)}\nTrigger: ${safe(r.trigger)}\nCurrent: ${safe(r.status) || '-'}\n\nWhat should suggested status be?`,
}}];

const sd = $getWorkflowStaticData('global');
function safe(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]()~>#+\-=|{}.!\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const chatId = $json.chat_id;
const queue = sd.reviewQueue || [];
const i = (sd.review && sd.review.i) || 0;
const r = queue[i] || {};
const fix = $json.fix_status || '';

const draft = {
  chat_id: chatId,
  callback_id: $json.callback_id || '',
  ack: 'Saved fix',
  type: 'sheet_rule_correction',
  account_no: `row_${r.row}`,
  old_status: r.status || '',
  new_status: fix,
  validation_result: 'Human Sheet Fix',
  decision_source: 'telegram_review',
  matched_keyword: r.trigger || '',
  confidence: 'Human',
  reason: `Sheet row ${r.row} trigger "${r.trigger}" marked wrong; correct status=${fix}`,
  example_comment: r.group || '',
};

sd.review.i = Math.min(i + 1, queue.length);
const ni = sd.review.i;
if (ni >= queue.length) {
  sd.mode = ''; sd.review = null;
  return [{ json: {
    ...draft,
    text: `Saved correction for row ${safe(r.row)} -> ${safe(fix)}\n\nReview finished (${queue.length} rules).`,
  }}];
}
const n = queue[ni];
const text =
`Saved: row ${safe(r.row)} -> ${safe(fix)}\n\n` +
`Sheet review ${ni+1}/${queue.length}\n` +
`Row ${safe(n.row)} | group: ${safe(n.group)}\n` +
`Trigger: ${safe(n.trigger)}\n` +
`Suggested: ${safe(n.status) || '-'}\n\n` +
`Is this rule correct?`;
return [{ json: { ...draft, text } }];

const sd2=$getWorkflowStaticData('global');
function safe(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]()~>#+\-=|{}.!\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function fold(t){return String(t||'').toLowerCase().replace(/ı/g,'i').replace(/ş/g,'s').replace(/ğ/g,'g').replace(/ç/g,'c').replace(/ö/g,'o').replace(/ü/g,'u').replace(/['"`]/g,'').replace(/[;,.\|]+/g,' ').replace(/\s+/g,' ').trim();}
const chatId = sd2._askChat || $json.chat_id;
const userText = String(sd2._askText || $json.text || '');
const rows = $input.all().map(i=>i.json).filter(j=>j && (j.trigger_phrase||j.Trigger));
const active = rows.filter(j=>String(j.active??'true').toLowerCase()!=='false');
const norm = fold(userText);
const hits=[];
for (const j of active){
  const trigger=String(j.trigger_phrase||j.Trigger||'').trim();
  const t=fold(trigger);
  if(t.length>=2 && norm.includes(t)){
    hits.push({
      row: j.row_number ?? j.row ?? '?',
      trigger, status:String(j.suggested_status||j.first_status||'').trim(),
      group:String(j.keyword_group||'').trim(),
      len:t.length
    });
  }
}
hits.sort((a,b)=>b.len-a.len);
const top=hits.slice(0,8);
let text;
if(!top.length){
  text=`No sheet trigger matched:\n${safe(userText)}\nScanned active: ${active.length}`;
} else {
  text=`Sheet matches for:\n${safe(userText)}\n\n`+top.map((h,i)=>`${i+1}) Row ${safe(h.row)} | ${safe(h.group)}\n   ${safe(h.trigger)} -> ${safe(h.status)}`).join('\n\n');
}
return [{ json: { chat_id: chatId, text: text.slice(0,3500) } }];

const route = $('Route Update').item.json;
const item = $input.first();
const binary = item.binary || {};
const key = Object.keys(binary)[0];
if (!key) throw new Error('Telegram download returned no binary');
const b = binary[key];
// ensure filename present for V2 kind detection
if (!b.fileName) b.fileName = route.file_name || 'upload.xlsx';
if (!b.mimeType && route.mime_type) b.mimeType = route.mime_type;
return [{
  json: {
    chat_id: route.chat_id,
    file_name: b.fileName
  },
  binary: { file: b }
}];

const j = $input.first().json;
return [{
  json: {
    ...j,
    _action: 'survey_vote',
    account: String(j.account || ''),
    status: String(j.status || ''),
    code: String(j.code || ''),
    chat_id: String(j.chat_id || ''),
    chatId: String(j.chat_id || '')
  }
}];
